	[SerializeField]
	protected string omenLogicDescriptionID;

	public virtual string GetLocalizedOmenLogicDescription(BattleAction battleAction, int actionValue)
	{
		return ReferenceSingleton<LocalizationManager>.Instance.GetLocalizedString(omenLogicDescriptionID);
	}

	public virtual void ActivateOmen(BattleAction battleAction, int actionValue, GameObject target, GameObject source, CorruptionPurifyModifierEnum corruptionPurifyModifierEnum = CorruptionPurifyModifierEnum.NONE, bool playSFX = false)
	{
	}

	public virtual List<GameObject> GetTargets()
	{
		return new List<GameObject>();
	}
}
